// Arma el prompt del Agente Info: le inyecta TODA la tabla bot.info_negocio
// (via Datos Info) + la pregunta. El agente redacta SOLO con estos datos.
const d = $('Leer Intención').first().json;
let filas = [];
try {
  filas = $('Datos Info').all().map((i) => i.json).filter((r) => r && r.clave && r.valor);
} catch (e) { filas = []; }
const tabla = filas.map((r) => '- ' + r.clave + ': ' + String(r.valor).trim()).join('\n');
return [{ json: {
  ...d,
  infoFilas: filas.length,
  promptInfo: [
    'DATOS DEL NEGOCIO (unica fuente de verdad; no afirmes nada que no este aca):',
    tabla || '(sin datos)',
    '',
    'PREGUNTA DEL CLIENTE:',
    String(d.userMessage || ''),
  ].join('\n'),
} }];
